BEGIN;

-- Existing data is checked as part of applying this migration.
ALTER TABLE learning_course
    ALTER COLUMN estimated_study_time_in_hours SET NOT NULL;

ALTER TABLE learning_course
    ADD CONSTRAINT learning_course_range_ck
    CHECK (
        estimated_study_time_in_hours >= 1
        AND estimated_study_time_in_hours <= 1000
    );

-- Application inserts and direct database writes share this constraint.
COMMIT;

